let th=document.createElement('div');th.id='royalThemeShade';th.innerHTML='<div class="royalModal"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><h2>🎨 Luxury Themes & Customize</h2><button id="royalThemeClose" type="button">Close ✕</button></div><p class="muted">24 theme presets plus custom colors. The original Royal Store logo stays unchanged.</p><div id="royalThemeGrid" class="royalThemeGrid"></div><h3>Custom colors</h3><div class="royalFields"><label>Background<input id="royalBgColor" type="color" value="#080808"></label><label>Panel<input id="royalPanelColor" type="color" value="#171512"></label><label>Accent<input id="royalAccentColor" type="color" value="#e4c36a"></label></div><p><button id="royalApplyCustom" type="button">Apply Colors</button> <button id="royalResetTheme" type="button" class="secondary">Reset Royal Gold</button></p><p class="muted">Theme settings are saved in this browser on this device.</p></div>';if(location.pathname==='/admin')document.body.appendChild(th);
