function renderCart(){if(!$('royalCartRows'))return;let total=0,count=0;$('royalCartRows').innerHTML=cart.map(r=>{let p=items.find(x=>x.id===r.id)||r.product,price=Number(p.price||0),qty=Math.max(1,Number(r.qty||1));count+=qty;if(price>0)total+=price*qty;return '<div class="royalCartRow"><div><b>'+safe(p.name)+'</b><br><span class="muted">'+safe(p.category||'')+' · '+(price>0?'Rs. '+price.toLocaleString('en-PK'):'Price on request')+'</span><br><button type="button" data-remove-cart="'+safe(r.id)+'" class="secondary">Remove</button></div><div class="royalQty"><button type="button" data-dec="'+safe(r.id)+'">−</button><b>'+qty+'</b><button type="button" data-inc="'+safe(r.id)+'">+</button></div></div>'}).join('')||'<p>Cart empty — products par Add to Cart dabayein.</p>';$('royalCartCount').textContent=count;$('royalCartSum').textContent='Priced items subtotal: Rs. '+total.toLocaleString('en-PK')+(cart.some(r=>Number((items.find(p=>p.id===r.id)||r.product).price||0)<=0)?' · Some items need a quote.':'');$('royalCartRows').querySelectorAll('[data-inc]').forEach(b=>b.onclick=()=>{let r=cart.find(x=>x.id===b.dataset.inc);if(r)r.qty=Math.min(999,r.qty+1);persist()});$('royalCartRows').querySelectorAll('[data-dec]').forEach(b=>b.onclick=()=>{let r=cart.find(x=>x.id===b.dataset.dec);if(r)r.qty=Math.max(1,r.qty-1);persist()});$('royalCartRows').querySelectorAll('[data-remove-cart]').forEach(b=>b.onclick=()=>{cart=cart.filter(x=>x.id!==b.dataset.removeCart);persist()})}
