async function placeOrder(e){e.preventDefault();if(!cart.length)return;let f=Object.fromEntries(new FormData(e.target)),orderItems=cart.map(r=>{let p=items.find(x=>x.id===r.id)||r.product;return{id:p.id,name:p.name,category:p.category,quantity:r.qty,price:Number(p.price||0),lineTotal:Number(p.price||0)*r.qty}}),summary=orderItems.map(x=>x.name+' x '+x.quantity+(x.price?' (Rs '+x.price+')':' (price on request)')).join('; '),total=orderItems.reduce((n,x)=>n+x.lineTotal,0),payload={...f,item:summary,items:orderItems,quantity:orderItems.reduce((n,x)=>n+x.quantity,0),total,city:f.city,address:f.address,details:f.details||'',paymentMethod:f.paymentMethod};$('royalCheckoutStatus').textContent='Saving order…';try{let r=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),d=await r.json();if(!r.ok)throw Error(d.error||'Order save failed');let msg='Assalam-o-Alaikum Royal Mobile & Printing Store.\nOrder: '+d.orderId+'\nName: '+f.name+'\nPhone: '+f.phone+'\nCity: '+f.city+'\nAddress: '+f.address+'\nPayment: '+f.paymentMethod+'\nItems: '+summary+'\nPriced items subtotal: Rs '+total+'\nNotes: '+(f.details||'-')+'\nPlease confirm final stock, rates and delivery.';$('royalCheckoutStatus').textContent='Order saved: '+d.orderId+'. Opening WhatsApp.';localStorage.setItem('royalLastOrderV2',JSON.stringify({orderId:d.orderId,payload}));cart=[];persist();window.location.href='https://wa.me/923040011041?text='+encodeURIComponent(msg)}catch(err){$('royalCheckoutStatus').textContent='Order could not be saved: '+err.message+'. Please retry.'}}
