 if(p==="/api/admin/promotions"){let a=await get(env,"promotions",[]);if(m==="GET")return json({promotions:a});if(m==="POST"){let b;try{b=await req.json()}catch{return json({error:"Invalid JSON"},400)}if(!String(b.title||"").trim())return json({error:"Promotion title required"},400);if(b.image&&String(b.image).startsWith('data:image/')&&String(b.image).length>500000)return json({error:'Promotion image must be under 500 KB after compression'},413);const row={id:crypto.randomUUID(),type:b.type==='bulk'?'bulk':'single',title:String(b.title).slice(0,160),details:String(b.details||"").slice(0,2000),startDate:String(b.startDate||'').slice(0,20),endDate:String(b.endDate||'').slice(0,20),offer:String(b.offer||"").slice(0,240),wasPrice:b.wasPrice===null||b.wasPrice===undefined?null:Number(b.wasPrice),nowPrice:b.nowPrice===null||b.nowPrice===undefined?null:Number(b.nowPrice),image:String(b.image||"").slice(0,500000),active:b.active!==false,createdAt:new Date().toISOString()};a.push(row);await put(env,"promotions",a);return json({ok:true,promotion:row},201)}}
